head.script:
scwin.onpageload = function() {
	dataList1.setData([1, 'a', 2, 'b', 3, 'c', 4, 'd', 5, 'e', 6, 'f', 6, 'g']);
};
scwin.custom_oncontextopen = function(row, col) {
	return {
		hideSystemMenu: ["ColumnFix"],
		appendMenu: [
			{ label: "컬럼 틀고정", userMenuId: "ColumnFix", className: "userMenu" },
			{ label: "우측컬럼 틀고정", userMenuId: "ColumnRightFix", className: "userMenu" },
			{ label: "행 틀고정", userMenuId: "RowFix", className: "userMenu" },
			{ label: "그리드 컬럼 배경색", userMenuId: "ColumnBackgroundColor", className: "userMenu" },
			{ label: "그리드 행 배경색", userMenuId: "RowBackgroundColor", className: "userMenu" },
			{ label: "그리드 컬럼 폰트색", userMenuId: "ColumnColor", className: "userMenu" },
			{ label: "그리드 행 폰트색", userMenuId: "RowColor", className: "userMenu" },
			{ label: "선택 컬럼 숨기기", userMenuId: "userColumnHide", className: "userMenu" },
			{ label: "전체 컬럼 숨기기 해제", userMenuId: "userShowAll", className: "userMenu" }
		]
	};
};
